-- Let me check all tables for any column containing 'rde' or 'equity'
SELECT table_name, column_name FROM information_schema.columns 
WHERE column_name LIKE '%rde%' OR column_name LIKE '%equity%';

-- Check all numeric columns in beneficiariesandassessments
SELECT column_name, data_type FROM information_schema.columns 
WHERE table_name = 'beneficiariesandassessments' AND data_type IN ('numeric', 'decimal', 'double precision', 'real', 'integer', 'bigint');

-- Check all tables for columns that might be related to equity or distribution
SELECT table_name, column_name, data_type FROM information_schema.columns 
WHERE (column_name LIKE '%equity%' OR column_name LIKE '%distribut%') AND table_schema = 'public';
